PRAGMA foreign_keys = ON;
CREATE TABLE organizations (id TEXT PRIMARY KEY,name TEXT NOT NULL,plan TEXT NOT NULL,users INTEGER NOT NULL DEFAULT 0,active_projects INTEGER NOT NULL DEFAULT 0,documents_processed INTEGER NOT NULL DEFAULT 0,ai_requests INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE users (id TEXT PRIMARY KEY,name TEXT NOT NULL,email TEXT NOT NULL UNIQUE,password_hash TEXT NOT NULL,role TEXT NOT NULL CHECK(role IN ('Individual','Finance User','Professional User')),professional_role TEXT NOT NULL,organization_id TEXT NOT NULL,organization_name TEXT NOT NULL,active INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY (organization_id) REFERENCES organizations(id));
CREATE INDEX idx_users_org ON users(organization_id);
CREATE TABLE clients (id TEXT PRIMARY KEY,name TEXT NOT NULL,company TEXT NOT NULL,industry TEXT NOT NULL,email TEXT NOT NULL DEFAULT '',phone TEXT NOT NULL DEFAULT '',fy TEXT NOT NULL,status TEXT NOT NULL,team TEXT NOT NULL,projects INTEGER NOT NULL DEFAULT 0,documents INTEGER NOT NULL DEFAULT 0,organization_id TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY (organization_id) REFERENCES organizations(id));
CREATE INDEX idx_clients_org ON clients(organization_id);
CREATE TABLE projects (id TEXT PRIMARY KEY,name TEXT NOT NULL,client_id TEXT NOT NULL,client_name TEXT NOT NULL,type TEXT NOT NULL,fy TEXT NOT NULL,currency TEXT NOT NULL,status TEXT NOT NULL,priority TEXT NOT NULL,start_date TEXT NOT NULL,end_date TEXT NOT NULL,team_json TEXT NOT NULL DEFAULT '[]',tags_json TEXT NOT NULL DEFAULT '[]',organization_id TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY (organization_id) REFERENCES organizations(id),FOREIGN KEY (client_id) REFERENCES clients(id));
CREATE INDEX idx_projects_org ON projects(organization_id);
CREATE TABLE documents (id TEXT PRIMARY KEY,name TEXT NOT NULL,type TEXT NOT NULL,size TEXT NOT NULL,status TEXT NOT NULL,uploaded_by TEXT NOT NULL,uploaded_at TEXT NOT NULL,client_id TEXT NOT NULL,project_id TEXT NOT NULL,organization_id TEXT NOT NULL,pages INTEGER,storage_key TEXT,mime_type TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY (organization_id) REFERENCES organizations(id),FOREIGN KEY (client_id) REFERENCES clients(id),FOREIGN KEY (project_id) REFERENCES projects(id));
CREATE INDEX idx_documents_project ON documents(project_id);
CREATE TABLE tasks (id TEXT PRIMARY KEY,title TEXT NOT NULL,client TEXT NOT NULL,project TEXT NOT NULL,assignee TEXT NOT NULL,priority TEXT NOT NULL,due TEXT NOT NULL,status TEXT NOT NULL,organization_id TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY (organization_id) REFERENCES organizations(id));
CREATE INDEX idx_tasks_org_status ON tasks(organization_id,status);
CREATE TABLE conversations (id TEXT PRIMARY KEY,user_id TEXT NOT NULL,project_id TEXT,agent_id TEXT NOT NULL,title TEXT NOT NULL DEFAULT 'New conversation',organization_id TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY (user_id) REFERENCES users(id),FOREIGN KEY (project_id) REFERENCES projects(id),FOREIGN KEY (organization_id) REFERENCES organizations(id));
CREATE TABLE messages (id TEXT PRIMARY KEY,conversation_id TEXT NOT NULL,role TEXT NOT NULL CHECK(role IN ('user','assistant')),content TEXT NOT NULL,created_at TEXT NOT NULL,evidence_json TEXT,calculation TEXT,assumptions_json TEXT,limitations TEXT,FOREIGN KEY (conversation_id) REFERENCES conversations(id) ON DELETE CASCADE);
CREATE INDEX idx_messages_conversation ON messages(conversation_id,created_at);
CREATE TABLE conversation_files (conversation_id TEXT NOT NULL,document_id TEXT NOT NULL,PRIMARY KEY (conversation_id,document_id),FOREIGN KEY (conversation_id) REFERENCES conversations(id) ON DELETE CASCADE,FOREIGN KEY (document_id) REFERENCES documents(id));
CREATE TABLE compliance_items (id TEXT PRIMARY KEY,title TEXT NOT NULL,client TEXT NOT NULL,due_date TEXT NOT NULL,category TEXT NOT NULL,status TEXT NOT NULL,organization_id TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY (organization_id) REFERENCES organizations(id));
CREATE TABLE knowledge_items (id TEXT PRIMARY KEY,title TEXT NOT NULL,kind TEXT NOT NULL,owner TEXT NOT NULL,updated TEXT NOT NULL,organization_id TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY (organization_id) REFERENCES organizations(id));
CREATE TABLE audit_logs (id TEXT PRIMARY KEY,actor TEXT NOT NULL,action TEXT NOT NULL,resource TEXT NOT NULL,timestamp TEXT NOT NULL,organization_id TEXT NOT NULL,metadata_json TEXT,FOREIGN KEY (organization_id) REFERENCES organizations(id));
CREATE INDEX idx_audit_org_time ON audit_logs(organization_id,timestamp);
CREATE TABLE settings (organization_id TEXT PRIMARY KEY,data_json TEXT NOT NULL DEFAULT '{}',updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY (organization_id) REFERENCES organizations(id));
CREATE INDEX idx_documents_client ON documents(client_id);
